#!/bin/bash
# SOURCE 1 -- the six published NNFX combinations through PROTOCOL.md.
# Do NOT edit this file while it is running: bash reads a script incrementally
# as it executes, which is why s234c/d/e.sh are separate files and why
# exit6.sh had to be restored on 25 Nov.
cd /Users/jackcuster/fx-data
export FX_COST_TABLE=results/cost_table_h22.csv
LOG=results/chainlogs/src1.log
ts(){ date "+[%H:%M:%S]"; }
echo "$(ts) START src1" >> $LOG
python3 code/nnfxsrc1.py --nulls 200 >> $LOG 2>&1 && echo "$(ts) OK src1" >> $LOG || echo "$(ts) FAIL src1" >> $LOG
echo "$(ts) DONE src1" >> $LOG
